contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address other, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(other != address(this), "other must differ from test contract");
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "test contract must have enough Ether");

        uint256 otherBefore = c.balances(other); if (__ESBMC_reverted()) return;
        uint256 selfBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;

        c.Deposit{value: amount}(); if (__ESBMC_reverted()) return;

        uint256 otherAfter = c.balances(other); if (__ESBMC_reverted()) return;
        uint256 selfAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(selfAfter == selfBefore + amount && otherAfter == otherBefore);
    }

    receive() external payable {}
}

